bg=7
out=[[bg]*22 for _ in range(22)]
# tiles: (top,left,border,inside), output positions inferred
objs=[(3,0,8,6),(12,5,8,4),(16,0,8,2),(5,17,2,1),(9,12,2,5),(17,12,2,6)]
